package $P.domain;

public class DomainException extends RuntimeException {

    public enum Kind {
        INVALID_REQUEST(400),
        ROOM_NOT_FOUND(404),
        RESERVATION_NOT_FOUND(404),
        ROOM_UNAVAILABLE(409),
        OPERATION_NOT_ALLOWED(409),
        CAPACITY_EXCEEDED(422);

        private final int httpStatus;

        Kind(int httpStatus) {
            this.httpStatus = httpStatus;
        }

        public int httpStatus() {
            return httpStatus;
        }
    }

    private final Kind kind;

    public DomainException(Kind kind, String message) {
        super(message);
        this.kind = kind;
    }

    public Kind kind() {
        return kind;
    }
}
EOF

cat > domain/Money.java <<EOF
package $P.domain;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

public final class Money {

    public static final BigDecimal ZERO = new BigDecimal("0.00");

    private Money() {
    }

    /** Arredonda para centavos, meio para o par. */
    public static BigDecimal round(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN);
    }

    /** Escreve como "R\$ 1.234,56". */
    public static String format(BigDecimal value) {
        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
        symbols.setDecimalSeparator(',');
        symbols.setGroupingSeparator('.');
        return "R\$ " + new DecimalFormat("#,##0.00", symbols).format(value);
    }
}
EOF

