cat > notification/HousekeepingNotice.java <<EOF
package $P.notification;

import $P.domain.Formats;
import $P.domain.Reservation;
import $P.domain.ReservationListener;
import $P.domain.ReservationStatus;

/** Avisa a governança para preparar o quarto, ou que as datas ficaram livres. */
public class HousekeepingNotice implements ReservationListener {

    private final MessageLog log;
    private final String address;

    public HousekeepingNotice(MessageLog log, String address) {
        this.log = log;
        this.address = address;
    }

    @Override
    public void onConfirmed(Reservation r) {
        log.send(Channel.EMAIL, address, "Reserva confirmada - quarto " + r.room().number(),
                "A reserva " + r.id() + " do quarto " + r.room().number() + " foi confirmada.\n"
                        + "Entrada: " + Formats.date(r.checkIn()) + "\n"
                        + "Saída: " + Formats.date(r.checkOut()) + "\n"
                        + "Hóspedes: " + r.guests());
    }

    @Override
    public void onCancelled(Reservation r, ReservationStatus previous) {
        if (previous != ReservationStatus.CONFIRMED) {
            return;
        }
        log.send(Channel.EMAIL, address, "Reserva cancelada - quarto " + r.room().number(),
                "A reserva " + r.id() + " do quarto " + r.room().number() + " foi cancelada.\n"
                        + "Datas liberadas: de " + Formats.date(r.checkIn()) + " a " + Formats.date(r.checkOut()));
    }
}
EOF

cat > notification/FinanceNotice.java <<EOF
package $P.notification;

import java.math.BigDecimal;

import $P.domain.Money;
import $P.domain.Reservation;
import $P.domain.ReservationListener;
import $P.domain.ReservationStatus;

/** Avisa o financeiro dos pagamentos recebidos e dos reembolsos a fazer. */
public class FinanceNotice implements ReservationListener {

    private final MessageLog log;
    private final String address;

    public FinanceNotice(MessageLog log, String address) {
        this.log = log;
        this.address = address;
    }

    @Override
    public void onConfirmed(Reservation r) {
        log.send(Channel.EMAIL, address, "Pagamento recebido - reserva " + r.id(),
                "Recebemos o pagamento da reserva " + r.id() + ".\n"
                        + "Valor pago: " + Money.format(r.amountPaid()));
    }

    @Override
    public void onCancelled(Reservation r, ReservationStatus previous) {
        if (previous != ReservationStatus.CONFIRMED || r.refund().compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        log.send(Channel.EMAIL, address, "Reembolso - reserva " + r.id(),
